"""Write the contracts, actions, step forms, file policies and step pages from runtime/specs.py.

Run from the repository root: ``python tests/build_contracts.py``.
``tests/test_contracts.py`` fails when a committed file differs from what this writes.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path
from typing import Any

import yaml

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from runtime import limits, specs  # noqa: E402

HEADER = (
    "# Generated by tests/build_contracts.py from runtime/specs.py.\n"
    "# Do not edit by hand: tests/test_contracts.py fails when this file drifts.\n"
)
ARTIFACT_MAX_BYTES = 200 * limits.MiB
ARTIFACT_MAX_ENV = "FS_EXTENSION_ARTIFACT_MAX_BYTES"

_OUTPUT_SCHEMA: dict[str, Any] = {
    "strings": {"type": "array", "items": {"type": "string"}},
    "objects": {"type": "array", "items": {"type": "object"}},
    "any_items": {"type": "array"},
    "any": {"type": ["object", "array", "string", "number", "integer", "boolean", "null"]},
}
_NULLABLE = {
    "text": "string",
    "integer": "integer",
    "boolean": "boolean",
    "artifact_handle": "string",
    "object": "object",
}
_ACTION_TYPE = {
    "text": "string",
    "integer": "integer",
    "boolean": "boolean",
    "object": "object",
    "array": "array",
    "json": "object",
    "artifact_handle": "artifact_handle",
}


class _Dumper(yaml.SafeDumper):
    def ignore_aliases(self, data: Any) -> bool:
        return True


def _str_presenter(dumper: yaml.SafeDumper, data: str) -> Any:
    if "\n" in data:
        return dumper.represent_scalar("tag:yaml.org,2002:str", data, style="|")
    return dumper.represent_scalar("tag:yaml.org,2002:str", data)


_Dumper.add_representer(str, _str_presenter)


def dump(value: Any) -> str:
    return HEADER + yaml.dump(value, Dumper=_Dumper, sort_keys=False, allow_unicode=True, width=100)


# ---------------------------------------------------------------------------
# Inputs


def _field_schema(field: specs.Field) -> dict[str, Any]:
    if field.value_type == "json":
        schema: dict[str, Any] = dict(_OUTPUT_SCHEMA["any"])
    else:
        schema = {"type": {"text": "string"}.get(field.value_type, field.value_type)}
    schema["title"] = field.title
    schema["description"] = field.description
    if field.options:
        schema["enum"] = list(field.options)
    if field.default is not None:
        schema["default"] = field.default
    if field.minimum is not None:
        schema["minimum"] = field.minimum
    if field.maximum is not None:
        schema["maximum"] = field.maximum
    if field.max_length is not None:
        schema["maxLength"] = field.max_length
    return schema


TEXT_TITLES = {
    "xml": "XML",
    "left": "First document",
    "right": "Second document",
    "schema": "Schema (XSD)",
    "stylesheet": "Stylesheet (XSLT)",
    "records": "Records",
    "data": "JSON",
    "csv": "CSV",
}


def document_inputs(document: specs.Document) -> list[dict[str, Any]]:
    """The two inputs of a document: its text and its file."""
    items: list[dict[str, Any]] = []
    if document.text_field:
        if document.many:
            schema: dict[str, Any] = {
                "type": "array",
                "items": {"type": "string"},
                "title": "Documents as text",
                "description": document.description,
            }
            value_type = "array"
        elif document.kind in {"json", "records"}:
            schema = dict(_OUTPUT_SCHEMA["any"])
            schema.update(title=TEXT_TITLES[document.key], description=document.description)
            value_type = "json"
        else:
            schema = {
                "type": "string",
                "title": TEXT_TITLES[document.key],
                "description": document.description,
            }
            value_type = "text"
        items.append(
            {
                "name": document.text_field,
                "value_type": value_type,
                "required": False,
                "schema": schema,
            }
        )
    file_description = _file_description(document)
    if document.many:
        items.append(
            {
                "name": document.file_field,
                "value_type": "array",
                "required": False,
                "schema": {
                    "type": "array",
                    "items": {"type": "string"},
                    "title": MANY_TITLES[document.file_field],
                    "description": file_description,
                },
            }
        )
    else:
        items.append(
            {
                "name": document.file_field,
                "value_type": "artifact_handle",
                "required": document.required and not document.text_field,
                "description": file_description,
            }
        )
    return items


MANY_TITLES = {"xml_files": "Documents as files", "schema_files": "Other schema files"}
#: Inputs that hold a list of workflow files.
FILE_LISTS = frozenset(MANY_TITLES)


def _file_description(document: specs.Document) -> str:
    if document.file_field == "schema_files":
        return (
            "The schema's other files (included or imported), as workflow files or one ZIP of "
            "them. Only these are ever read."
        )
    if document.many:
        return "The documents as workflow files, in order (for example from File Transfer)."
    if document.kind == "xlsx":
        return "The XLSX file, as a workflow file (for example from File Transfer)."
    other = "" if not document.text_field else ", or give it as text instead"
    noun = document.label.removeprefix("The ")
    return f"The {noun} as a workflow file (for example from File Transfer){other}."


def _inputs(operation: specs.Operation) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for document in operation.documents:
        items.extend(document_inputs(document))
    for field in operation.fields:
        items.append(
            {
                "name": field.name,
                "value_type": field.value_type,
                "required": field.required,
                "schema": _field_schema(field),
            }
        )
    return items


# ---------------------------------------------------------------------------
# Outputs


def _output_schema(output: specs.Output) -> dict[str, Any]:
    if output.schema_type in _OUTPUT_SCHEMA:
        schema = dict(_OUTPUT_SCHEMA[output.schema_type])
    elif output.value_type in _NULLABLE:
        schema = {"type": [_NULLABLE[output.value_type], "null"]}
    elif output.value_type == "array":
        schema = {"type": "array"}
    else:
        schema = dict(_OUTPUT_SCHEMA["any"])
    schema["description"] = output.description
    return schema


def outputs_of(operation: specs.Operation) -> list[specs.Output]:
    outputs: list[specs.Output] = []
    spec = operation.file_output
    if spec is not None:
        outputs.append(specs.Output("file", "artifact_handle", spec.description))
        if spec.inline_field:
            outputs.append(
                specs.Output(
                    spec.inline_field,
                    "json" if spec.inline_json else "text",
                    spec.inline_description,
                    "any" if spec.inline_json else None,
                )
            )
    if spec is not None and spec.presentation:
        outputs.append(
            specs.Output(
                spec.presentation,
                "object",
                "The file's name and type for display (html and text output); none for xml.",
            )
        )
    names = {o.name for o in outputs}
    outputs.extend(o for o in operation.outputs if o.name not in names)
    if spec is not None:
        for fact in ("size_bytes", "sha256"):
            if fact not in {o.name for o in outputs}:
                outputs.append(next(o for o in specs.FILE_FACTS if o.name == fact))
    return outputs


def _outputs(operation: specs.Operation) -> list[dict[str, Any]]:
    return [
        {"name": o.name, "value_type": o.value_type, "schema": _output_schema(o)}
        for o in outputs_of(operation)
    ]


# ---------------------------------------------------------------------------
# Files


def _scopes(operation: specs.Operation) -> list[str]:
    scopes = ["extension:invoke"]
    if operation.documents and any(d.file_field for d in operation.documents):
        scopes.append("artifact:read")
    if operation.file_output is not None:
        scopes.append("artifact:write")
    return scopes


def operation_manifest() -> dict[str, Any]:
    operations = []
    for operation in specs.OPERATIONS:
        operations.append(
            {
                "operation_id": operation.operation_id,
                "display_name": operation.display_name,
                "description": operation.description,
                "operation_kind": "action" if operation.file_output else "source",
                "category": "data",
                "workflow_visible": True,
                "inputs": _inputs(operation),
                "outputs": _outputs(operation),
                "result_fields": [f"result.{o.name}" for o in outputs_of(operation)],
                "error_codes": specs.all_error_codes(operation),
            }
        )
    return {"operations": operations}


def artifact_policies() -> dict[str, Any]:
    policies = []
    for operation in specs.OPERATIONS:
        entry: dict[str, Any] = {"operation_id": operation.operation_id}
        inputs = []
        for document in operation.documents:
            inputs.append(
                {
                    "kind": "artifact",
                    "value_type": "artifact_handle",
                    "binding_key": document.file_field,
                    "field": document.file_field,
                    "required": document.required and not document.text_field,
                    "max_size_bytes": ARTIFACT_MAX_BYTES,
                    "max_size_env": ARTIFACT_MAX_ENV,
                }
            )
        if inputs:
            entry["inputs"] = inputs
        spec = operation.file_output
        if spec is not None:
            entry["outputs"] = [
                {
                    "kind": "artifact",
                    "value_type": "artifact_handle",
                    "binding_key": "result_file",
                    "filename": spec.filename,
                    "content_type": spec.content_type,
                    "max_size_bytes": ARTIFACT_MAX_BYTES,
                    "max_size_env": ARTIFACT_MAX_ENV,
                    "retention_class": "run_window",
                    **(
                        {"presentation": {"claim_output": spec.presentation}}
                        if spec.presentation
                        else {}
                    ),
                }
            ]
        policies.append(entry)
    return {"artifact_policies": policies}


def _action_parameter(item: dict[str, Any]) -> dict[str, Any]:
    parameter = {
        "name": item["name"],
        "type": _ACTION_TYPE[item["value_type"]],
        "required": item["required"],
    }
    description = item.get("description") or item.get("schema", {}).get("description")
    if description:
        parameter["description"] = description
    return parameter


def actions() -> dict[str, Any]:
    rows = []
    for operation in specs.OPERATIONS:
        rows.append(
            {
                "action_id": operation.operation_id,
                "title": operation.display_name,
                "description": operation.description,
                "required_scopes": _scopes(operation),
                "handler": {"mode": "extension"},
                "mutates_platform": False,
                "workflow_visible": True,
                "parameters": [_action_parameter(i) for i in _inputs(operation)],
                "result_fields": [o.name for o in outputs_of(operation)],
                "error_codes": specs.all_error_codes(operation),
            }
        )
    return {"actions": rows}


def _widget(item: dict[str, Any], field: specs.Field | None) -> str:
    if item["value_type"] == "artifact_handle" or item["name"] in FILE_LISTS:
        return "artifact_picker"
    if field is not None and field.options:
        return "select"
    return {
        "text": "text" if field is not None else "textarea",
        "integer": "number",
        "boolean": "boolean",
    }.get(item["value_type"], "json")


def step_forms() -> dict[str, Any]:
    forms = []
    for operation in specs.OPERATIONS:
        by_name = {f.name: f for f in operation.fields}
        fields = []
        for item in _inputs(operation):
            field = by_name.get(item["name"])
            widget = _widget(item, field)
            schema = item.get("schema", {})
            entry: dict[str, Any] = {
                "name": item["name"],
                "label": schema.get("title") or _file_label(item["name"]),
                "widget_type": widget,
                "required": item["required"],
                "help_text": schema.get("description") or item.get("description", ""),
            }
            if widget == "select" and field is not None:
                entry["options"] = [{"label": o, "value": o} for o in field.options]
            fields.append(entry)
        forms.append(
            {
                "operation_id": operation.operation_id,
                "title": operation.display_name,
                "fields": fields,
            }
        )
    return {"forms": forms}


def _file_label(name: str) -> str:
    return {
        "xml_file": "XML file",
        "left_file": "First document file",
        "right_file": "Second document file",
        "schema_file": "Schema file",
        "stylesheet_file": "Stylesheet file",
        "records_file": "Records file",
        "json_file": "JSON file",
        "csv_file": "CSV file",
        "xlsx_file": "XLSX file",
    }.get(name, name)


# ---------------------------------------------------------------------------
# Pages

_TYPE_WORDS = {
    "text": "text",
    "integer": "whole number",
    "boolean": "yes/no",
    "object": "object",
    "array": "list",
    "json": "JSON",
    "artifact_handle": "workflow file",
}

PAGES: tuple[tuple[str, str, str, tuple[str, ...]], ...] = (
    (
        "xml-steps-read",
        "Read and check",
        "Steps that read, select and check XML.",
        ("read", "select", "check"),
    ),
    (
        "xml-steps-convert",
        "Build and convert",
        "Steps that build XML and convert it.",
        ("build", "transform"),
    ),
    (
        "xml-steps-edit",
        "Edit and compare",
        "Steps that change, format and compare XML.",
        ("edit", "utility"),
    ),
)


def _step_markdown(operation: specs.Operation) -> str:
    lines = [f"### {operation.display_name}", "", operation.description, ""]
    kind = "saves a file" if operation.file_output else "returns values"
    lines.append(f"Action id `{operation.operation_id}` · {kind}")
    lines += ["", "**Inputs**", ""]
    for item in _inputs(operation):
        schema = item.get("schema", {})
        description = schema.get("description") or item.get("description", "")
        required = ", required" if item["required"] else ""
        word = _TYPE_WORDS.get(item["value_type"], item["value_type"])
        lines.append(f"- `{item['name']}` ({word}{required}): {description}")
    lines += ["", "**Results**", ""]
    for output in outputs_of(operation):
        word = _TYPE_WORDS.get(output.value_type, output.value_type)
        lines.append(f"- `{output.name}` ({word}): {output.description}")
    if operation.example:
        lines += ["", f"Example: {operation.example}"]
    return "\n".join(lines) + "\n"


def step_page(page_id: str) -> dict[str, Any]:
    _, title, description, groups = next(p for p in PAGES if p[0] == page_id)
    names = dict(specs.GROUPS)
    components = []
    for group in groups:
        steps = [op for op in specs.OPERATIONS if op.group == group]
        body = "\n".join(_step_markdown(op) for op in steps)
        components.append(
            {
                "component_id": f"steps_{group}",
                "type": "markdown",
                "title": names[group],
                "body": body,
            }
        )
    return {
        "page_id": page_id,
        "title": title,
        "description": description,
        "components": components,
    }


def changelog_page() -> dict[str, Any]:
    text = (ROOT / "CHANGELOG.md").read_text(encoding="utf-8")
    body = re.sub(r"^# Changelog\s*\n+", "", text)
    return {
        "page_id": "changelog",
        "title": "Changelog",
        "description": "What changed in each release of this extension.",
        "components": [
            {
                "component_id": "changelog_entries",
                "type": "markdown",
                "title": "Release history",
                "body": body,
            }
        ],
    }


def generated_files() -> dict[str, str]:
    files = {
        "contracts/operation_manifest.yaml": dump(operation_manifest()),
        "contracts/artifact_policies.yaml": dump(artifact_policies()),
        "contracts/step_ui_manifest.yaml": dump(step_forms()),
        "ui/actions/actions.yaml": dump(actions()),
        "ui/pages/changelog.yaml": dump(changelog_page()),
    }
    for page_id, *_ in PAGES:
        files[f"ui/pages/{page_id}.yaml"] = dump(step_page(page_id))
    return files


def main() -> int:
    for relative, text in generated_files().items():
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        print(f"wrote {relative}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
